package com.sharkie.wobblekit;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;
public class MainActivity extends Activity {
 WobbleView view;Handler handler=new Handler();Runnable animation;static final String PREF="wobble";static final String IMAGE_FILE="wallpaper-image";
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff15151c);LinearLayout bar=new LinearLayout(this);String[] labels={"Image","+ Zone","Play/Edit","Wallpaper"};int buttonHeight=(int)(56*getResources().getDisplayMetrics().density+0.5f);for(int i=0;i<labels.length;i++){final int n=i;Button button=new Button(this);button.setText(labels[i]);button.setTextSize(11);bar.addView(button,new LinearLayout.LayoutParams(0,buttonHeight,1));button.setOnClickListener(v->action(n));}root.addView(bar);view=new WobbleView(this);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);loadSaved();animation=()->{view.tick();handler.postDelayed(animation,16);};handler.post(animation);}
 void action(int n){if(n==0){openImagePicker();}else if(n==1){view.addZone();saveZones();}else if(n==2){view.editing=!view.editing;saveZones();Toast.makeText(this,view.editing?"Edit zones":"Boing! :3",0).show();}else{saveZones();Intent i=new Intent(android.app.WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(android.app.WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,WobbleWallpaper.class));startActivity(i);}}
 void openImagePicker(){Intent document=new Intent(Intent.ACTION_OPEN_DOCUMENT);document.setType("image/*");document.addCategory(Intent.CATEGORY_OPENABLE);document.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(document,1);}catch(android.content.ActivityNotFoundException ex){Intent fallback=new Intent(Intent.ACTION_GET_CONTENT);fallback.setType("image/*");fallback.addCategory(Intent.CATEGORY_OPENABLE);fallback.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(fallback,1);}catch(android.content.ActivityNotFoundException fallbackEx){Toast.makeText(this,"No image picker is available on this device.",Toast.LENGTH_LONG).show();}}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==1&&result==RESULT_OK&&data!=null){try{android.net.Uri uri=data.getData();if(uri==null)throw new IOException("The image picker returned no image.");try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=openFileOutput(IMAGE_FILE,MODE_PRIVATE)){if(in==null)throw new IOException("Unable to read the selected image.");byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);}Bitmap image=BitmapFactory.decodeFile(new File(getFilesDir(),IMAGE_FILE).getAbsolutePath());if(image==null)throw new IOException("The selected file is not a readable image.");view.load(image);getPreferences(0).edit().putBoolean("hasImage",true).apply();saveZones();}catch(IOException|SecurityException ex){Toast.makeText(this,"Couldn't load image: "+ex.getMessage(),Toast.LENGTH_LONG).show();}}}
 void loadSaved(){try{if(getPreferences(0).getBoolean("hasImage",false)){Bitmap b=BitmapFactory.decodeFile(new File(getFilesDir(),IMAGE_FILE).getAbsolutePath());if(b==null)throw new IOException("Saved image is unreadable.");view.load(b);String z=getPreferences(0).getString("zones","");for(String item:z.split(";")){String[] p=item.split(",");if(p.length==3)view.zones.add(new WobbleView.Zone(Float.parseFloat(p[0]),Float.parseFloat(p[1]),Float.parseFloat(p[2])));}}}catch(IOException|NumberFormatException ex){Toast.makeText(this,"Couldn't restore saved image: "+ex.getMessage(),Toast.LENGTH_LONG).show();}}
 void saveZones(){StringBuilder b=new StringBuilder();for(WobbleView.Zone z:view.zones)b.append(z.x).append(',').append(z.y).append(',').append(z.r).append(';');getPreferences(0).edit().putString("zones",b.toString()).apply();}
 @Override protected void onPause(){saveZones();super.onPause();} @Override protected void onDestroy(){handler.removeCallbacks(animation);super.onDestroy();}
}
